import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import type { JpoDocument } from "@daily-route/transit";

/**
 * The committed JPO registry.
 *
 * It is read once at process start. The file is generated by `pnpm data:jpo`
 * and is not a live service: the official layer changes rarely, and the map,
 * the planner and the assistant must read the same frozen answer.
 */
export function loadJpoDocument(): JpoDocument | null {
  try {
    const raw = readFileSync(resolve(import.meta.dirname, "../../../data/jpo-network.json"), "utf8");
    return JSON.parse(raw) as JpoDocument;
  } catch {
    return null;
  }
}
